export const cleanMaskapaiDisplayName = (name?: string, vendorName?: string): string => {
  if (!name) return "";
  let clean = name;
  if (vendorName) {
    const escapedVendor = vendorName.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
    clean = clean.replace(new RegExp(`\\s*\\(${escapedVendor}\\)`, 'gi'), '');
  }
  // Strip known vendor names in parentheses
  clean = clean.replace(/\s*\((?:DAHLIA|IBU DAHLIA|NQH WISATA|NQH|PT BURGUNDY|Madani Tour|PT Cemerlang|PT AZZA BAROKAH MADINAH|PT AZZAHRA HARAMAIN WISATA|PT\. Darmawisata Indonesia|HAINANTIKET\.COM|PT ARRAYYAN AL MUBARAK|FATAYA|FRESHNEL|SAUDI AIRLINES|KANG RAFI)\)/gi, '');
  return clean.trim();
};

// Map rawMaskapaiData to guarantee unique IDs
export const maskapaiData: Maskapai[] = rawMaskapaiData.map((item) => {
  const vendorPrefix = item.namaVendor ? item.namaVendor.replace(/[^a-zA-Z0-9]/g, '').toLowerCase() : 'vendor';
  return {
    ...item,
    name: cleanMaskapaiDisplayName(item.name, item.namaVendor),
    id: `${vendorPrefix}-${item.id}`
  };
});
